// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Img,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

const { fontFamily } = loadFont();



export type AnatomyPulseProps = Record<string, any>;

const AnatomyPulse: React.FC<AnatomyPulseProps> = ({
  backgroundColor = "#07172E",
  transparentBackground = false,
  durationInSeconds = 10,
  anatomyImage = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/d1e05e58c3f64824ae0a5d650bbbc7f2.svg",
  pulseColor = "#FF3B30",
  pulseBaseSize = 80,
  pulseSpeed = 0.8,
  pulseCount = 3,
  labelFontSize = 22,
  pulsePoints = [
    { label: "Brain", xPercent: 50, yPercent: 10, isActive: true },
    { label: "Heart", xPercent: 51, yPercent: 34, isActive: true },
    { label: "Left Lung", xPercent: 46, yPercent: 33, isActive: true },
    { label: "Right Lung", xPercent: 55, yPercent: 33, isActive: true },
    { label: "Knee", xPercent: 54, yPercent: 88, isActive: true },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Render a single pulsing location with its label
  const PulseRings = ({
    x,
    y,
    label,
  }: {
    x: number;
    y: number;
    label: string;
  }) => {
    // Determine label positioning dynamically to stay within bounds
    // xPercent < 30 -> place label to the right
    // xPercent > 70 -> place label to the left
    // Otherwise, place above or below depending on vertical position
    let labelStyle: React.CSSProperties = {
      position: "absolute",
      whiteSpace: "nowrap",
      fontFamily,
      fontSize: `${labelFontSize * s}px`,
      fontWeight: "bold",
      color: "#FFFFFF",
      backgroundColor: "rgba(7, 23, 46, 0.85)",
      border: `${1.5 * s}px solid ${pulseColor}`,
      borderRadius: `${6 * s}px`,
      padding: `${6 * s}px ${12 * s}px`,
      pointerEvents: "none",
      zIndex: 20,
      boxShadow: `0 0 ${10 * s}px rgba(0,0,0,0.5)`,
    };

    if (x < 30) {
      labelStyle = {
        ...labelStyle,
        left: `calc(50% + ${pulseBaseSize * 0.45 * s}px)`,
        top: "50%",
        transform: "translateY(-50%)",
      };
    } else if (x > 70) {
      labelStyle = {
        ...labelStyle,
        right: `calc(50% + ${pulseBaseSize * 0.45 * s}px)`,
        top: "50%",
        transform: "translateY(-50%)",
      };
    } else if (y < 20) {
      labelStyle = {
        ...labelStyle,
        left: "50%",
        top: `calc(50% + ${pulseBaseSize * 0.45 * s}px)`,
        transform: "translateX(-50%)",
      };
    } else {
      labelStyle = {
        ...labelStyle,
        left: "50%",
        bottom: `calc(50% + ${pulseBaseSize * 0.45 * s}px)`,
        transform: "translateX(-50%)",
      };
    }

    // Gentle entry animation for the label based on frame
    const labelOpacity = interpolate(frame, [0, 15], [0, 1], {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    return (
      <div
        style={{
          position: "absolute",
          left: `${x}%`,
          top: `${y}%`,
          transform: "translate(-50%, -50%)",
          width: pulseBaseSize * s,
          height: pulseBaseSize * s,
          pointerEvents: "none",
          zIndex: 10,
        }}
      >
        {Array.from({ length: pulseCount }).map((_, i) => {
          // Calculate a continuous looping progress from 0 to 1
          const loopDurationFrames = fps / pulseSpeed;
          // Offset each ring evenly so they follow each other
          const offsetFrame = frame + (loopDurationFrames / pulseCount) * i;
          const progress = (offsetFrame % loopDurationFrames) / loopDurationFrames;

          // Scale from 10% to 150% of the base size
          const scale = interpolate(progress, [0, 1], [0.1, 1.5]);
          
          // Fade in quickly, then fade out slowly as it expands
          const opacity = interpolate(
            progress,
            [0, 0.1, 0.8, 1],
            [0, 0.8, 0.2, 0]
          );

          const strokeWidth = 2.5 * s;
          const glowSpread = 6 * s;

          return (
            <div
              key={i}
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                margin: "auto",
                width: "100%",
                height: "100%",
                border: `${strokeWidth}px solid ${pulseColor}`,
                borderRadius: "50%",
                transform: `scale(${scale})`,
                opacity: opacity,
                boxShadow: `0 0 ${glowSpread}px ${pulseColor}, inset 0 0 ${glowSpread}px ${pulseColor}`,
                transition: "none",
              }}
            />
          );
        })}
        
        {/* Core glow at the center of the pulse */}
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: 12 * s,
            height: 12 * s,
            backgroundColor: pulseColor,
            borderRadius: "50%",
            opacity: 0.7 + Math.sin(frame * 0.1) * 0.3, // slight constant flicker
            boxShadow: `0 0 ${15 * s}px ${pulseColor}`,
            transition: "none",
            zIndex: 15,
          }}
        />

        {/* Dynamic bounds-safe Label */}
        {label && (
          <div style={{ ...labelStyle, opacity: labelOpacity }}>
            {label}
          </div>
        )}
      </div>
    );
  };

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        background: transparentBackground
          ? "transparent"
          : `radial-gradient(circle at center, ${backgroundColor} 0%, #030812 100%)`,
        overflow: "hidden",
      }}
    >
      <AbsoluteFill style={{ padding: `${40 * s}px` }}>
        <Img
          src={anatomyImage}
          style={{
            width: "100%",
            height: "100%",
            objectFit: "contain",
            opacity: 0.85,
          }}
        />

        {/* Render active pulse points over the anatomy */}
        {pulsePoints
          .filter((p) => p.isActive)
          .map((point, index) => (
            <PulseRings
              key={`${point.label}-${index}`}
              x={point.xPercent}
              y={point.yPercent}
              label={point.label}
            />
          ))}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default AnatomyPulse;